const a = ($input.first().json.body) || $input.first().json;
const sevMap = { LOW: 1, MEDIUM: 2, HIGH: 3 };
const ports = Array.isArray(a.ports) ? a.ports.join(', ') : (a.ports || '');
const payload = {
  type: 'ids',
  source: 'homelab-ids',
  sourceRef: `${a.rule_id || 'IDS'}-${a.timestamp || Date.now()}`,
  title: `${a.rule_id || ''} ${a.rule_name || 'IDS alert'}`.trim(),
  description: `Rule: ${a.rule_id} - ${a.rule_name}\nSeverity: ${a.severity}\nSource IP: ${a.src_ip || 'N/A'}\nDest IP: ${a.dst_ip || 'N/A'}\nPorts: ${ports}\nCount: ${a.count || 'N/A'}\nTime: ${a.timestamp || ''}`,
  severity: sevMap[a.severity] || 2,
  tags: ['ids', 'homelab', a.rule_id].filter(Boolean)
};
return [{ json: payload }];
